'use strict';
// Writes case/fake-store.js = a short header + the whole of case/case-store.js, so a page that loads only
// fake-store.js (no load order to get right) still gets the full store API. Run by `npm run sync:case`;
// tests/case-store.test.js fails if the two files drift apart.
const fs = require('node:fs');
const path = require('node:path');
const dir = path.join(__dirname, '..', 'case');
const HEADER = `/*
 * GENERATED by scripts/build-fake-store.js from case-store.js. Do not edit; run \`npm run sync:case\`.
 * Self-contained copy of the case store, for pages that load only this file.
 * Use WebSaathiCase.createFakeStore() (in memory) or WebSaathiCase.createStore() (chrome.storage.local).
 */
`;
function build() {
  fs.writeFileSync(path.join(dir, 'fake-store.js'), HEADER + fs.readFileSync(path.join(dir, 'case-store.js'), 'utf8'));
}
if (require.main === module) { build(); console.log('built case/fake-store.js'); }
module.exports = { build };
